input.new_string:
/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */
export const PROJECT_KEY_MAX_LENGTH = 4;

export function projectKeyFromName(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  const letters =
    words.length >= 2
      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
      : (words[0] ?? "task").slice(0, 3);
  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, PROJECT_KEY_MAX_LENGTH) || "TASK";
}

/**
 * A key already present in `taken` is made unique the way a slug is: by
 * appending 2, 3, … The stem is trimmed so the result never exceeds four
 * characters and still matches `^[A-Z][A-Z0-9]+$`.
 */
export function uniqueProjectKey(key: string, taken: Iterable<string>): string {
  const used = new Set([...taken].map((item) => item.toUpperCase()));
  const base = normalizeProjectKey(key);
  if (!used.has(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const suffixText = String(suffix);
    const stemLength = PROJECT_KEY_MAX_LENGTH - suffixText.length;
    if (stemLength < 1) continue;
    const candidate = `${base.slice(0, stemLength)}${suffixText}`;
    if (/^[A-Z][A-Z0-9]+$/.test(candidate) && !used.has(candidate)) {
      return candidate;
    }
  }
  throw new InvalidSlugError(base, "exhausted unique key suffixes");
}

function normalizeProjectKey(key: string): string {
  const cleaned = key
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "")
    .slice(0, PROJECT_KEY_MAX_LENGTH);
  if (/^[A-Z][A-Z0-9]+$/.test(cleaned)) return cleaned;
  const derived = projectKeyFromName(key);
  if (/^[A-Z][A-Z0-9]+$/.test(derived)) return derived;
  return "TASK";
}

