/** Guard for archive actions, so double-archiving is a domain-level conflict. */
export function assertNotArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (isArchived(row)) {
    throw new AlreadyArchivedError(entity, id);
  }
}

export class NotArchivedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly entity: string, readonly id: string) {
    super(`${entity} ${id} is not archived.`);
    this.name = "NotArchivedError";
  }
}

/** Guard for restore actions. A live row has nothing to restore. */
export function assertArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (!isArchived(row)) {
    throw new NotArchivedError(entity, id);
  }
}

