import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runMigrations } from "@/server/db/migrate";
import { subscribe } from "@/lib/event-bus";
import { registerUsageListeners } from "@/server/services/usage-service";
import * as projectService from "@/server/services/project-service";
import * as issueService from "@/server/services/issue-service";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { createTenant, issueInput } from "./tests/server/_support/fixtures";

async function main(): Promise<void> {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-repro-"));
  const path = join(dir, "taskflow.db");
  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);
  const off = registerUsageListeners();

  try {
    const tenant = await createTenant("freebie", "free");
    // seed usage to the one live project so the meter starts honest
    await usageRepo.incrementUsage(tenant.org.id, { projectsUsed: 1 });

    await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Second", slug: "second", key: "SEC" }),
    );
    console.log("after second", await usageRepo.getUsage(tenant.org.id), await projectRepo.countProjects(tenant.org.id));

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    console.log(
      "after archive",
      (await usageRepo.getUsage(tenant.org.id)).projectsUsed,
      "live",
      await projectRepo.countProjects(tenant.org.id),
      "all",
      await projectRepo.countProjects(tenant.org.id, { includeArchived: true }),
    );

    const created = await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Web Visitors", slug: "web-visitors", key: "WV" }),
    );
    console.log("visitors", created.slug, created.key);

    const vendors = await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Web Vendors", slug: "web-vendors", key: "WV" }),
    ).catch(async (error: unknown) => {
      // free plan only allows 2 live; archive freed one, so this is the second live? 
      // live after archive = 1 (second), plus visitors = 2. vendors should hit the limit.
      console.log("vendors blocked", error instanceof Error ? error.message : error);
      return null;
    });
    console.log("vendors result", vendors && { slug: vendors.slug, key: vendors.key });

    // key collision on a roomier plan
    const growth = await createTenant("growthy", "growth");
    await usageRepo.incrementUsage(growth.org.id, { projectsUsed: 1 });
    const a = await projectService.createProject(
      growth.actors.member,
      projectInput(growth.org.id, { name: "Web Visitors", slug: "web-visitors", key: "WV" }),
    );
    const b = await projectService.createProject(
      growth.actors.member,
      projectInput(growth.org.id, { name: "Web Vendors", slug: "web-vendors", key: "WV" }),
    );
    console.log("keys", a.key, b.key, a.slug, b.slug);

    await projectService.archiveProject(growth.actors.admin, {
      orgId: growth.org.id,
      projectId: a.id,
      archiveIssues: true,
    });
    const c = await projectService.createProject(
