    }
    const archivedRow = await projectRepo.findProjectById(stat.org.id, stat.project.id);
    console.log("archived status", archivedStatus, archivedRow?.status);

    // done+archived issues allow completion
    const emptyish = await createTenant("emptyish", "growth");
    const doneIssue = await issueService.createIssue(
      emptyish.actors.member,
      issueInput(emptyish.org.id, emptyish.project.id, { title: "Done" }),
    );
    await issueService.changeIssueStatus(emptyish.actors.member, {
      orgId: emptyish.org.id,
      issueId: doneIssue.id,
      status: "done",
    });
    const canceled = await issueService.createIssue(
      emptyish.actors.member,
      issueInput(emptyish.org.id, emptyish.project.id, { title: "Cancel" }),
    );
    await issueService.changeIssueStatus(emptyish.actors.member, {
      orgId: emptyish.org.id,
      issueId: canceled.id,
      status: "canceled",
    });
    const archivedIssue = await issueService.createIssue(
      emptyish.actors.member,
