    const keys = await createTenant("keys", "growth");
    const first = await projectService.createProject(
      keys.actors.member,
      projectInput(keys.org.id, { name: "Platform X", slug: "platform-x", key: "PLAT" }),
    );
    console.log("duplicate PLAT became", first.key);

    console.log("second id", second.id);
  } finally {
    off();
    rmSync(dir, { recursive: true, force: true });
  }
}

