    <form action={submit} className="space-y-5">
      {state?.ok === true ? (
        <p className="rounded bg-emerald-50 px-3 py-2 text-sm text-emerald-700">
          Project updated.
70→        </p>
      ) : null}
      {state?.ok === false ? (
        <p className="rounded bg-rose-50 px-3 py-2 text-sm text-rose-700">
          {state.error.message}
